01 long long fastPow(long long b, long long e, long long mod) {
02     long long result = 1;
03     while (e > 0) {
04         if (e & 1)
05             result = result * b % mod;
06             b = b * b % mod;
07             e >>= 1;
08     }
09     return result;
10 }
```

